            new GlossaryEntry("0502", 5, "파티클 시스템", "Emission (Rate / Burst)", "계속 뿜기 / 한 번에 터뜨리기", "\"피격 시 Burst로 파편 20개를 한 번에 뿌려줘.\"", "0502_EmissionRateBurst"),
            new GlossaryEntry("0503", 5, "파티클 시스템", "Start Lifetime / Speed / Size", "입자 수명·속도·크기", "\"수명 0.5초, 속도 5, 크기 0.1~0.3 랜덤으로 설정해줘.\"", "0503_LifetimeSpeedSize"),
            new GlossaryEntry("0504", 5, "파티클 시스템", "Shape (Cone, Sphere, Edge)", "입자가 나오는 모양", "\"Cone 30도로 위쪽으로 뿜는 연기를 만들어줘.\"", "0504_ParticleShape"),
            new GlossaryEntry("0505", 5, "파티클 시스템", "Color / Size over Lifetime", "시간에 따라 색·크기 변화", "\"노랑→빨강→투명으로 변하고 점점 작아지게 해줘.\"", "0505_ColorSizeOverLifetime"),
            new GlossaryEntry("0506", 5, "파티클 시스템", "Gravity Modifier / Noise", "중력 / 흔들리는 움직임", "\"불씨가 Noise로 흔들리며 위로 올라가게 해줘.\"", "0506_GravityNoise"),
            new GlossaryEntry("0507", 5, "파티클 시스템", "Sub Emitter", "입자가 죽을 때 또 다른 입자 생성", "\"불꽃놀이: 올라가다 죽으면 Sub Emitter로 터지게 해줘.\"", "0507_SubEmitter"),
            new GlossaryEntry("0508", 5, "파티클 시스템", "Trail / Trail Renderer", "지나간 자리에 꼬리", "\"칼 휘두를 때 Trail Renderer로 검기를 남겨줘.\"", "0508_TrailRenderer"),
            new GlossaryEntry("0509", 5, "파티클 시스템", "Collision (파티클)", "입자가 바닥에 부딪힘", "\"빗방울이 바닥에 닿으면 튀는 파티클을 Collision 모듈로 만들어줘.\"", "0509_ParticleCollision"),
            new GlossaryEntry("0510", 5, "파티클 시스템", "Texture Sheet Animation", "파티클에 프레임 애니메이션", "\"폭발 스프라이트 시트 4x4를 Texture Sheet Animation으로 재생해줘.\"", "0510_TextureSheetAnimation"),
            new GlossaryEntry("0511", 5, "파티클 시스템", "Billboard / Stretched Billboard", "항상 카메라를 봄 / 속도 방향으로 늘어짐", "\"스파크를 Stretched Billboard로 길쭉하게 날려줘.\"", "0511_Billboard"),
            new GlossaryEntry("0512", 5, "파티클 시스템", "Additive / Alpha Blend", "겹칠수록 밝아짐 / 일반 반투명", "\"마법 이펙트를 Additive 블렌딩으로 밝게 빛나게 해줘.\"", "0512_AdditiveAlphaBlend"),
            new GlossaryEntry("0513", 5, "대표 이펙트", "타격 이펙트 (Hit Effect)", "타격 순간 섬광·파편·정지·흔들림을 한 번에", "\"적에게 맞으면 하얀 섬광+파편 Burst+0.05초 히트스톱+작은 카메라 쉐이크를 함께 재생해줘.\"", "0513_HitEffect"),
            new GlossaryEntry("0514", 5, "대표 이펙트", "머즐 플래시", "총구에서 번쩍이는 짧은 빛", "\"총 쏠 때 총구에 0.05초 머즐 플래시와 Point Light를 깜빡여줘.\"", "0514_MuzzleFlash"),
            new GlossaryEntry("0515", 5, "대표 이펙트", "폭발", "섬광·화염·연기·파편·충격파를 겹친 폭발", "\"폭발: 섬광, 화염 구, 연기, 파편, 충격파 링 5개 레이어로 구성해줘.\"", "0515_Explosion"),
            new GlossaryEntry("0516", 5, "대표 이펙트", "오라 / 버프", "버프 중 몸 주변에 계속 도는 마법 이펙트", "\"버프 중에는 발밑에 회전하는 마법진과 위로 오르는 입자를 계속 재생해줘.\"", "0516_AuraBuff"),
            new GlossaryEntry("0517", 5, "대표 이펙트", "힐 이펙트", "회복할 때 올라가는 초록 입자", "\"회복 시 초록 입자가 몸 주변에서 나선형으로 올라가게 해줘.\"", "0517_HealEffect"),
            new GlossaryEntry("0518", 5, "대표 이펙트", "날씨 (비, 눈)", "카메라를 따라다니는 비·눈", "\"카메라를 따라다니는 비 파티클과 바닥 물튀김을 만들어줘.\"", "0518_Weather"),
            new GlossaryEntry("0519", 5, "대표 이펙트", "데미지 숫자 (Damage Popup)", "맞은 위치에 튀어오르는 숫자", "\"맞은 위치에 데미지 숫자가 튀어올랐다 사라지게 해줘. 치명타는 크고 빨갛게.\"", "0519_DamagePopup"),
            new GlossaryEntry("0520", 5, "대표 이펙트", "데칼 (Decal)", "벽·바닥에 붙이는 자국(총알 자국 등)", "\"총알 자국을 URP Decal Projector로 벽에 남기고 5초 후 사라지게 해줘.\"", "0520_Decal"),
            new GlossaryEntry("0521", 5, "대표 이펙트", "라인 렌더러 (Line Renderer)", "두 점 사이를 잇는 선(레이저·빔)", "\"레이저 빔을 Line Renderer로 그리고 맞은 지점에 스파크를 내줘.\"", "0521_LineRenderer"),
            new GlossaryEntry("0522", 5, "VFX Graph·화면 효과", "VFX Graph", "GPU로 수십만 입자 처리 (URP/HDRP)", "\"VFX Graph로 입자 5만 개짜리 소용돌이 포탈을 만들어줘.\"", "0522_VFXGraph"),
            new GlossaryEntry("0523", 5, "VFX Graph·화면 효과", "Volume / Post Processing", "화면 전체에 거는 필터", "\"URP Global Volume을 만들고 Bloom과 Color Adjustments를 추가해줘.\"", "0523_VolumePostProcessing"),
            new GlossaryEntry("0524", 5, "VFX Graph·화면 효과", "Bloom", "밝은 부분이 번져 빛남", "\"Emission 오브젝트만 빛나게 Bloom Threshold를 조절해줘.\"", "0524_Bloom"),
            new GlossaryEntry("0525", 5, "VFX Graph·화면 효과", "Vignette", "화면 가장자리 어둡게", "\"체력 30% 이하일 때 빨간 Vignette가 맥박처럼 깜빡이게 해줘.\"", "0525_Vignette"),
            new GlossaryEntry("0526", 5, "VFX Graph·화면 효과", "Chromatic Aberration", "색이 갈라지는 왜곡", "\"피격 순간 0.2초 Chromatic Aberration을 강하게 줘.\"", "0526_ChromaticAberration"),
            new GlossaryEntry("0527", 5, "VFX Graph·화면 효과", "Depth of Field", "배경 흐림 (초점)", "\"대화 중에는 Depth of Field로 배경을 흐리게 해줘.\"", "0527_DepthOfField"),
            new GlossaryEntry("0528", 5, "VFX Graph·화면 효과", "Motion Blur", "빠른 움직임 잔상", "\"대시할 때만 Motion Blur를 켜줘.\"", "0528_MotionBlur"),
            new GlossaryEntry("0529", 5, "VFX Graph·화면 효과", "Color Grading / LUT", "화면 색감 보정", "\"밤 장면은 푸른 톤, 던전은 채도 낮게 Color Grading 해줘.\"", "0529_ColorGrading"),
            new GlossaryEntry("0530", 5, "VFX Graph·화면 효과", "화면 전환 (Fade, Wipe)", "씬 전환 연출", "\"씬 이동 시 검은색 페이드 아웃→인을 0.5초씩 넣어줘.\"", "0530_ScreenTransition"),
            new GlossaryEntry("0601", 6, "", "Canvas / uGUI", "기본 UI 시스템", "\"uGUI로 체력바, 점수, 일시정지 버튼이 있는 HUD를 만들어줘.\"", "0601_CanvasUGUI"),
            new GlossaryEntry("0602", 6, "", "Canvas Scaler", "해상도별 UI 크기 맞춤", "\"1920x1080 기준으로 모바일에서도 UI가 깨지지 않게 Canvas Scaler를 설정해줘.\"", "0602_CanvasScaler"),
            new GlossaryEntry("0603", 6, "", "Anchor / Pivot", "UI 고정 기준점", "\"점수는 화면 오른쪽 위에 Anchor로 고정해줘.\"", "0603_AnchorPivot"),
            new GlossaryEntry("0604", 6, "", "TextMeshPro (TMP)", "선명한 글자 컴포넌트", "\"TextMeshPro로 한글 폰트 에셋을 만드는 법 알려줘.\"", "0604_TextMeshPro"),
            new GlossaryEntry("0605", 6, "", "Layout Group", "자동 정렬 (가로·세로·격자)", "\"Grid Layout Group으로 4x5 인벤토리 칸을 자동 배치해줘.\"", "0605_LayoutGroup"),
            new GlossaryEntry("0606", 6, "", "Scroll View", "스크롤 목록", "\"Scroll View에 상점 아이템 목록을 동적으로 생성해줘.\"", "0606_ScrollView"),
            new GlossaryEntry("0607", 6, "", "월드 스페이스 UI", "캐릭터 머리 위에 떠 있는 UI", "\"적 머리 위에 World Space 체력바를 띄우고 항상 카메라를 보게 해줘.\"", "0607_WorldSpaceUI"),
            new GlossaryEntry("0608", 6, "", "체력바 (딜레이 감소)", "깎인 부분이 늦게 따라 줄어듦", "\"체력바가 즉시 줄고 뒤의 흰 바가 0.5초 뒤 따라오게 해줘.\"", "0608_HealthBarDelay"),
            new GlossaryEntry("0609", 6, "", "쿨타임 UI (Radial Fill)", "원형으로 차오르는 쿨다운", "\"Image Fill Method Radial 360으로 스킬 쿨타임 UI를 만들어줘.\"", "0609_CooldownRadial"),
            new GlossaryEntry("0610", 6, "", "대화 시스템 / 타자 효과", "대사창, 한 글자씩 출력", "\"NPC 대화창에서 글자가 한 글자씩 나오고 클릭하면 전부 표시되게 해줘.\"", "0610_DialogueTypewriter"),
            new GlossaryEntry("0611", 6, "", "팝업 / 모달", "확인·취소 창", "\"'정말 나가시겠습니까?' 확인 팝업을 재사용 가능하게 만들어줘.\"", "0611_PopupModal"),
            new GlossaryEntry("0612", 6, "", "일시정지 메뉴", "Time.timeScale 0 + 메뉴", "\"ESC로 일시정지 메뉴(계속, 설정, 메인으로)를 열어줘.\"", "0612_PauseMenu"),
            new GlossaryEntry("0613", 6, "", "드래그 앤 드롭", "UI를 끌어다 놓기", "\"IDragHandler로 인벤토리 아이템을 드래그해서 슬롯끼리 교환해줘.\"", "0613_DragAndDrop"),
            new GlossaryEntry("0614", 6, "", "툴팁 (Tooltip)", "마우스 올리면 설명", "\"아이템에 마우스를 올리면 이름과 설명 툴팁을 띄워줘.\"", "0614_Tooltip"),
            new GlossaryEntry("0615", 6, "", "미니맵", "위에서 본 작은 지도", "\"Render Texture와 탑뷰 카메라로 미니맵을 만들어줘.\"", "0615_Minimap"),
            new GlossaryEntry("0616", 6, "", "로딩 화면 (비동기 로딩)", "진행률 표시하며 씬 로드", "\"LoadSceneAsync로 진행률 바가 있는 로딩 화면을 만들어줘.\"", "0616_AsyncLoading"),
            new GlossaryEntry("0617", 6, "", "조이스틱 (모바일)", "화면 가상 조이스틱", "\"모바일용 가상 조이스틱과 점프 버튼을 만들어줘.\"", "0617_VirtualJoystick"),
            new GlossaryEntry("0618", 6, "", "세이프 에어리어 (Safe Area)", "노치 영역 피하기", "\"아이폰 노치에 UI가 가리지 않게 Safe Area를 적용해줘.\"", "0618_SafeArea"),
            new GlossaryEntry("0701", 7, "", "FSM (유한 상태 기계)", "상태를 정해두고 조건에 따라 전환", "\"적 AI를 FSM으로 만들어줘: Idle, Patrol, Chase, Attack, Dead.\"", "0701_FSM"),
            new GlossaryEntry("0702", 7, "", "비헤이비어 트리 (Behavior Tree)", "복잡한 AI를 나무 구조로 판단", "\"보스 AI를 Behavior Tree 구조로 설계해줘. 체력 50% 이하면 패턴 변경.\"", "0702_BehaviorTree"),
            new GlossaryEntry("0703", 7, "", "NavMesh / NavMesh Agent", "자동 길찾기 지형 / 길찾는 주체", "\"AI Navigation 패키지로 NavMesh를 굽고 적이 플레이어를 추적하게 해줘.\"", "0703_NavMeshAgent"),
            new GlossaryEntry("0704", 7, "", "NavMesh Obstacle / Off-Mesh Link", "움직이는 장애물 / 점프·사다리 연결", "\"상자를 NavMesh Obstacle(Carve)로 만들어 적이 피해가게 해줘.\"", "0704_NavMeshObstacleLink"),
            new GlossaryEntry("0705", 7, "", "웨이포인트 순찰 (Patrol)", "지정 지점을 돌아다님", "\"웨이포인트 4개를 순서대로 순찰하고 각 지점에서 2초 대기하게 해줘.\"", "0705_WaypointPatrol"),
            new GlossaryEntry("0706", 7, "", "시야 판정 (Field of View)", "시야각·거리·가림 체크", "\"시야각 90도, 거리 10m, 벽에 가리면 못 보는 시야 판정을 만들어줘.\"", "0706_FieldOfView"),
            new GlossaryEntry("0707", 7, "", "어그로 (Aggro) / 위협 수준", "누구를 공격할지 우선순위", "\"데미지를 가장 많이 준 플레이어를 우선 공격하는 어그로 시스템을 만들어줘.\"", "0707_Aggro"),
            new GlossaryEntry("0708", 7, "", "스포너 (Spawner) / 웨이브", "적 생성기 / 단계별 등장", "\"웨이브마다 적 수가 5씩 늘어나는 웨이브 스포너를 만들어줘.\"", "0708_WaveSpawner"),
            new GlossaryEntry("0709", 7, "", "보스 패턴 / 페이즈", "공격 패턴 순환, 체력 구간별 변화", "\"보스가 3가지 패턴을 랜덤 반복하고 30% 이하에서 2페이즈로 바뀌게 해줘.\"", "0709_BossPhase"),
            new GlossaryEntry("0710", 7, "", "플로킹 (Flocking) / Boids", "무리지어 움직임", "\"물고기 떼가 Boids 알고리즘으로 무리 지어 헤엄치게 해줘.\"", "0710_Flocking"),
            new GlossaryEntry("0711", 7, "", "A* (A스타) / 타일 길찾기", "격자 맵 최단 경로", "\"2D 타일맵에서 A* 알고리즘으로 적 길찾기를 만들어줘.\"", "0711_AStar"),
            new GlossaryEntry("0712", 7, "", "투사체 예측 조준", "움직이는 대상을 미리 조준", "\"포탑이 플레이어 이동 속도를 고려해 예측 사격하게 해줘.\"", "0712_PredictiveAim"),
            new GlossaryEntry("0801", 8, "", "ScriptableObject", "코드와 분리된 데이터 파일", "\"아이템 데이터(이름, 아이콘, 가격, 효과)를 ScriptableObject로 만들어줘.\"", "0801_ScriptableObject"),
            new GlossaryEntry("0802", 8, "", "체력·데미지 시스템 (IDamageable)", "맞을 수 있는 모든 것에 공통 규칙", "\"IDamageable 인터페이스로 플레이어, 적, 상자 모두 데미지를 받게 해줘.\"", "0802_DamageSystem"),
            new GlossaryEntry("0803", 8, "", "무적 시간 (i-frame)", "맞은 직후 잠깐 무적 + 깜빡임", "\"피격 후 1초 무적이고 그동안 스프라이트가 깜빡이게 해줘.\"", "0803_IFrame"),
            new GlossaryEntry("0804", 8, "", "인벤토리", "아이템 보관·사용", "\"20칸 인벤토리를 만들고 같은 아이템은 최대 99개까지 겹치게(스택) 해줘.\"", "0804_Inventory"),
            new GlossaryEntry("0805", 8, "", "장비 / 스탯", "착용 시 능력치 변화", "\"무기 장착 시 공격력이 오르는 장비·스탯 시스템을 만들어줘.\"", "0805_EquipmentStats"),
            new GlossaryEntry("0806", 8, "", "버프 / 디버프 (상태이상)", "일정 시간 능력치 변화, 독·빙결", "\"독 디버프: 5초 동안 1초마다 데미지 3, 중첩 불가로 만들어줘.\"", "0806_BuffDebuff"),
            new GlossaryEntry("0807", 8, "", "스킬 / 쿨다운", "기술과 재사용 대기", "\"Q, W, E 스킬 3개와 각각 다른 쿨다운을 가진 스킬 시스템을 만들어줘.\"", "0807_SkillCooldown"),
            new GlossaryEntry("0808", 8, "", "경험치 / 레벨업", "성장 곡선", "\"필요 경험치가 레벨마다 1.2배씩 늘어나는 레벨업 시스템을 만들어줘.\"", "0808_LevelUp"),
            new GlossaryEntry("0809", 8, "", "드롭 테이블 (가중치 랜덤)", "확률별 아이템 드롭", "\"일반 70%, 희귀 25%, 전설 5% 가중치 랜덤 드롭 테이블을 만들어줘.\"", "0809_DropTable"),
            new GlossaryEntry("0810", 8, "", "상점 / 재화", "골드로 구매·판매", "\"골드로 아이템을 사고 팔 수 있는 상점을 만들어줘.\"", "0810_Shop"),
            new GlossaryEntry("0811", 8, "", "퀘스트 시스템", "목표·진행도·보상", "\"'슬라임 10마리 처치' 같은 퀘스트를 데이터로 추가할 수 있게 만들어줘.\"", "0811_QuestSystem"),
            new GlossaryEntry("0812", 8, "", "세이브 / 로드", "진행 저장", "\"플레이어 위치, 체력, 인벤토리를 JSON 파일로 저장하고 불러오게 해줘.\"", "0812_SaveLoad"),
            new GlossaryEntry("0813", 8, "", "PlayerPrefs", "간단한 설정값 저장", "\"사운드 볼륨과 최고 점수를 PlayerPrefs로 저장해줘.\"", "0813_PlayerPrefs"),
            new GlossaryEntry("0814", 8, "", "체크포인트 / 리스폰", "죽으면 마지막 지점에서 부활", "\"깃발을 지나면 체크포인트로 저장되고 죽으면 거기서 리스폰하게 해줘.\"", "0814_CheckpointRespawn"),
            new GlossaryEntry("0815", 8, "", "게임 매니저 / 게임 상태", "시작·플레이·일시정지·게임오버 관리", "\"GameManager로 Ready, Playing, Paused, GameOver 상태를 관리해줘.\"", "0815_GameManagerState"),
            new GlossaryEntry("0816", 8, "", "씬 관리 (Scene Load)", "화면 전환", "\"타이틀 → 게임 → 결과 씬으로 이동하고 점수를 넘겨줘.\"", "0816_SceneManagement"),
            new GlossaryEntry("0817", 8, "", "상호작용 (Interaction)", "E키로 문 열기·줍기", "\"가까이 가면 'E 상호작용' 표시가 뜨고 문, 상자, NPC에 공통 적용되게 해줘.\"", "0817_Interaction"),
            new GlossaryEntry("0818", 8, "", "타일맵 (Tilemap) / 절차적 생성", "2D 맵 칠하기 / 맵 자동 생성", "\"Tilemap에 랜덤 던전 방 10개를 절차적으로 생성해줘.\"", "0818_TilemapProcedural"),
            new GlossaryEntry("0819", 8, "", "로컬라이제이션", "다국어 지원", "\"Unity Localization 패키지로 한국어/영어 전환을 만들어줘.\"", "0819_Localization"),
            new GlossaryEntry("0901", 9, "", "AudioSource / AudioClip", "소리 내는 스피커 / 소리 파일", "\"점프할 때 AudioSource.PlayOneShot으로 효과음을 재생해줘.\"", "0901_AudioSourceClip"),
            new GlossaryEntry("0902", 9, "", "사운드 매니저", "소리 재생을 한곳에서 관리", "\"어디서든 SoundManager.Play(\"Hit\")로 부를 수 있는 사운드 매니저를 만들어줘.\"", "0902_SoundManager"),
            new GlossaryEntry("0903", 9, "", "Audio Mixer / Group", "BGM·효과음 볼륨 분리", "\"Audio Mixer로 Master, BGM, SFX 그룹을 나누고 설정창 슬라이더와 연결해줘.\"", "0903_AudioMixer"),
            new GlossaryEntry("0904", 9, "", "3D 사운드 (Spatial Blend)", "거리·방향에 따라 소리 크기 변화", "\"모닥불 소리를 3D로 만들고 10m 밖에서는 안 들리게 해줘.\"", "0904_SpatialSound"),
            new GlossaryEntry("0905", 9, "", "크로스페이드 (Crossfade)", "BGM을 부드럽게 교체", "\"전투 시작 시 평화 BGM에서 전투 BGM으로 2초 크로스페이드해줘.\"", "0905_Crossfade"),
            new GlossaryEntry("0906", 9, "", "피치 랜덤 (Pitch Variation)", "같은 소리 반복 시 지루함 방지", "\"발소리를 재생할 때마다 피치를 0.9~1.1 랜덤으로 바꿔줘.\"", "0906_PitchVariation"),
            new GlossaryEntry("0907", 9, "", "오디오 스냅샷 / 로우패스", "상황별 음향 변화, 먹먹한 소리", "\"일시정지 중엔 BGM이 먹먹하게 들리도록 Low Pass 필터 스냅샷을 만들어줘.\"", "0907_AudioSnapshotLowPass"),
            new GlossaryEntry("0908", 9, "", "리듬 / 비트 동기화", "음악 박자에 맞춰 이벤트", "\"AudioSettings.dspTime으로 BPM 120 박자에 맞춰 노트를 생성해줘.\"", "0908_RhythmSync"),
            new GlossaryEntry("1001", 10, "조명·렌더링", "렌더 파이프라인 (URP / HDRP / Built-in)", "그래픽 처리 방식", "\"Built-in 프로젝트를 URP로 바꾸고 분홍색 머티리얼을 고치는 법 알려줘.\"", "1001_RenderPipeline"),
            new GlossaryEntry("1002", 10, "조명·렌더링", "Directional / Point / Spot Light", "태양 / 전구 / 손전등", "\"플레이어가 Spot Light 손전등을 F키로 켜고 끄게 해줘.\"", "1002_LightTypes"),
            new GlossaryEntry("1003", 10, "조명·렌더링", "실시간 / 베이크 조명 (Lightmap)", "매 프레임 계산 / 미리 구워둠", "\"움직이지 않는 건물은 Baked 조명으로 구워서 성능을 올려줘.\"", "1003_RealtimeBakedLighting"),
            new GlossaryEntry("1004", 10, "조명·렌더링", "Shadow (그림자) 설정", "그림자 품질·거리", "\"모바일용으로 그림자 거리 30m, Soft Shadow 끄는 설정을 알려줘.\"", "1004_ShadowSettings"),
            new GlossaryEntry("1005", 10, "조명·렌더링", "Skybox / 환경광", "하늘 배경 / 전체 밝기", "\"낮→밤으로 Skybox와 조명 색이 바뀌는 낮밤 사이클을 만들어줘.\"", "1005_SkyboxAmbient"),
            new GlossaryEntry("1006", 10, "조명·렌더링", "Fog (안개)", "멀리 있는 것 흐리게", "\"던전에 짙은 Fog를 넣어 시야를 20m로 제한해줘.\"", "1006_Fog"),
            new GlossaryEntry("1007", 10, "조명·렌더링", "Render Texture", "카메라 화면을 텍스처로", "\"CCTV 화면을 Render Texture로 모니터에 띄워줘.\"", "1007_RenderTexture"),
            new GlossaryEntry("1008", 10, "조명·렌더링", "Sorting Layer / Order in Layer", "2D 그리는 순서", "\"2D에서 캐릭터가 나무 뒤로 가면 가려지도록 Y축 정렬해줘.\"", "1008_SortingLayer"),
            new GlossaryEntry("1009", 10, "조명·렌더링", "2D Light (URP 2D)", "2D 게임용 조명", "\"URP 2D Renderer로 횃불 주변만 밝은 2D 조명을 만들어줘.\"", "1009_Light2D"),
            new GlossaryEntry("1010", 10, "최적화", "Profiler", "성능 측정 도구", "\"Profiler에서 이 스파이크 원인을 찾는 방법을 알려줘.\"", "1010_Profiler"),
            new GlossaryEntry("1011", 10, "최적화", "오브젝트 풀링 (Object Pooling)", "만들고 지우는 대신 재사용", "\"총알을 Instantiate/Destroy 대신 ObjectPool<T>로 재사용하게 바꿔줘.\"", "1011_ObjectPooling"),
            new GlossaryEntry("1012", 10, "최적화", "Draw Call / Batching", "그리기 호출 수 / 묶어서 줄이기", "\"Draw Call을 줄이도록 Static Batching과 SRP Batcher 설정을 알려줘.\"", "1012_DrawCallBatching"),
            new GlossaryEntry("1013", 10, "최적화", "GPU Instancing", "같은 모델 대량 그리기", "\"나무 1000그루를 GPU Instancing으로 그려줘.\"", "1013_GPUInstancing"),
            new GlossaryEntry("1014", 10, "최적화", "LOD (Level of Detail)", "멀면 저품질 모델", "\"건물에 LOD Group 3단계를 설정해줘.\"", "1014_LOD"),
            new GlossaryEntry("1015", 10, "최적화", "Occlusion Culling", "가려진 것 안 그리기", "\"실내 맵에 Occlusion Culling을 굽는 법 알려줘.\"", "1015_OcclusionCulling"),
            new GlossaryEntry("1016", 10, "최적화", "Sprite Atlas", "2D 이미지 묶기", "\"UI 아이콘들을 Sprite Atlas로 묶어 Draw Call을 줄여줘.\"", "1016_SpriteAtlas"),
            new GlossaryEntry("1017", 10, "최적화", "GC (가비지) 줄이기", "메모리 쓰레기로 인한 끊김", "\"Update에서 GC Alloc이 생기는 코드를 찾아서 고쳐줘.\"", "1017_GCReduction"),
            new GlossaryEntry("1018", 10, "최적화", "Addressables", "리소스를 필요할 때 불러오기", "\"Addressables로 스테이지별 리소스를 따로 로드하게 해줘.\"", "1018_Addressables"),
            new GlossaryEntry("1019", 10, "최적화", "코루틴 / async", "시간 걸리는 작업 나눠 실행", "\"3초 뒤 문이 열리는 걸 코루틴으로 만들어줘.\"", "1019_CoroutineAsync"),
            new GlossaryEntry("1101", 11, "", "싱글톤 (Singleton)", "게임에 하나만 있는 관리자", "\"GameManager를 싱글톤으로 만들고 씬이 바뀌어도 유지(DontDestroyOnLoad)되게 해줘.\"", "1101_Singleton"),
            new GlossaryEntry("1102", 11, "", "이벤트 / 옵저버 (Action, UnityEvent)", "\"이 일이 생겼어\"를 방송, 듣는 쪽이 반응", "\"플레이어가 죽으면 OnPlayerDied 이벤트를 쏘고 UI와 사운드가 각각 반응하게 해줘.\"", "1102_EventObserver"),
            new GlossaryEntry("1103", 11, "", "인터페이스 (Interface)", "공통 규칙 약속", "\"IInteractable 인터페이스로 상호작용 대상을 통일해줘.\"", "1103_Interface"),
            new GlossaryEntry("1104", 11, "", "컴포넌트 분리", "한 스크립트에 다 넣지 않기", "\"이 PlayerController를 이동, 공격, 체력 스크립트로 나눠줘.\"", "1104_ComponentSplit"),
            new GlossaryEntry("1105", 11, "", "상태 패턴 (State Pattern)", "상태를 클래스로 분리", "\"플레이어 상태(Idle, Run, Jump, Attack)를 State 패턴으로 리팩터링해줘.\"", "1105_StatePattern"),
            new GlossaryEntry("1106", 11, "", "커맨드 패턴", "입력을 명령 객체로, 되돌리기 가능", "\"퍼즐 게임에 Undo가 되도록 Command 패턴을 적용해줘.\"", "1106_CommandPattern"),
            new GlossaryEntry("1107", 11, "", "프리팹 / 프리팹 변형 (Prefab Variant)", "재사용 오브젝트 / 일부만 바꾼 복사본", "\"기본 적 프리팹에서 빠른 적, 강한 적을 Prefab Variant로 만드는 법 알려줘.\"", "1107_PrefabVariant"),
            new GlossaryEntry("1108", 11, "", "[SerializeField] / [Header] / [Range]", "Inspector에 변수 노출·정리", "\"private 변수를 SerializeField로 노출하고 Header와 Range로 정리해줘.\"", "1108_InspectorAttributes"),
            new GlossaryEntry("1109", 11, "", "Gizmos", "씬 뷰에 보조선 그리기", "\"적의 시야 범위와 공격 범위를 OnDrawGizmos로 그려줘.\"", "1109_Gizmos"),
            new GlossaryEntry("1110", 11, "", "에디터 확장 (Custom Editor, EditorWindow)", "나만의 툴 버튼·창", "\"Inspector에 '적 10마리 생성' 버튼을 추가하는 Custom Editor를 만들어줘.\"", "1110_EditorExtension"),
            new GlossaryEntry("1111", 11, "", "디버그 로그 / Debug.DrawRay", "콘솔 출력 / 레이 시각화", "\"Raycast가 어디로 나가는지 Debug.DrawRay로 보여줘.\"", "1111_DebugDrawRay"),
            new GlossaryEntry("1112", 11, "", "버전 관리 (Git, .gitignore)", "작업 기록·백업", "\"유니티 프로젝트용 .gitignore와 Git LFS 설정을 알려줘.\"", "1112_VersionControl"),
            new GlossaryEntry("1113", 11, "", "빌드 설정 (PC, Android, WebGL)", "플랫폼 출력", "\"WebGL로 빌드해서 itch.io에 올리는 순서를 알려줘.\"", "1113_BuildSettings"),
        };
    }
